def ecoute_en_situation(titre, items, langue="en-GB"):
    """items : (phrase dite par la voix anglaise, question du personnage guide, [bonne réponse, autres choix…], aide facultative)."""
    return {"type": "ecoute", "titre": titre, "langue": langue, "items": [
        {"dire": i[0], "question": i[1], "choix": list(i[2]), "reponse": i[2][0], **({"aide": i[3]} if len(i) > 3 else {})} for i in items]}


